import React, { useEffect, useMemo, useState } from "react";
import { motion } from "framer-motion";

import AdminBookingTable from "../components/AdminBookingTable";
import AdminLayout from "../components/AdminLayout";
import api from "../services/api";
import { formatErrorMessage } from "../utils/errorMessages";

const AdminHistory = () => {
  const [history, setHistory] = useState(null);
  const [message, setMessage] = useState("");
  const [refreshing, setRefreshing] = useState(false);

  const loadHistory = async (force = false) => {
      const cached = localStorage.getItem("adminHistory");
      if (!force && cached) {
        setHistory(JSON.parse(cached));
      }
      try {
        const response = await api.get("/admin/history", { cache: !force });
        setHistory(response.data || []);
        localStorage.setItem("adminHistory", JSON.stringify(response.data || []));
      } catch (error) {
        setMessage(formatErrorMessage(error.response?.data?.detail, "Something went wrong"));
        setHistory([]);
      }
    };

  useEffect(() => {
    loadHistory();
  }, []);

  const handleRefresh = async () => {
    setRefreshing(true);
    api.clearCache(["/admin/history"]);
    try {
      await loadHistory(true);
    } finally {
      setRefreshing(false);
    }
  };

  const processedBookings = useMemo(
    () => history?.filter((booking) => ["approved", "rejected"].includes(booking.status)) || history,
    [history]
  );

  return (
    <AdminLayout title="History" subtitle="Approved and rejected records from your block." onRefresh={handleRefresh} refreshing={refreshing}>
      {message ? <motion.div className="alert info" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>{String(message)}</motion.div> : null}
      <AdminBookingTable bookings={processedBookings} />
    </AdminLayout>
  );
};

export default AdminHistory;
